import os
from typing import Dict, Any, Optional

from openai import OpenAI


class TextContentSafety:
    def __init__(
        self,
        api_key: Optional[str] = None,
        model: str = "omni-moderation-latest",
        thresholds: Optional[Dict[str, float]] = None,
    ) -> None:
        self.client = OpenAI(api_key=api_key or os.environ.get("OPENAI_API_KEY"))
        self.model = model
        self.thresholds = thresholds or {
            "violence": 0.7,
            "violence/graphic": 0.5,
            "harassment": 0.8,
            "harassment/threatening": 0.4,
            "hate": 0.8,
            "hate/threatening": 0.4,
            "self-harm": 0.6,
            "self-harm/intent": 0.4,
            "self-harm/instructions": 0.3,
            "sexual": 0.9,
            "sexual/minors": 0.01,
            "illicit": 0.7,
            "illicit/violent": 0.4,
        }

    def evaluate(self, text: str) -> Dict[str, Any]:
        response = self.client.moderations.create(
            model=self.model,
            input=text,
        )

        result = response.results[0]

        category_scores = {}
        if hasattr(result, "category_scores") and result.category_scores is not None:
            category_scores = {
                key: float(value)
                for key, value in result.category_scores.model_dump().items()
            }

        categories = {}
        if hasattr(result, "categories") and result.categories is not None:
            categories = {
                key: bool(value)
                for key, value in result.categories.model_dump().items()
            }

        triggered = {}
        for category, threshold in self.thresholds.items():
            score = category_scores.get(category)
            if score is not None and score >= threshold:
                triggered[category] = {
                    "score": score,
                    "threshold": threshold,
                }

        allowed = len(triggered) == 0

        return {
            "allowed": allowed,
            "model": self.model,
            "flagged_by_provider": bool(getattr(result, "flagged", False)),
            "category_scores": category_scores,
            "categories": categories,
            "triggered": triggered,
        }
